// Общие шаги «מכשירים» для тестов #272dc6 / #83f7f9 (не тест: файл без .test.mjs).
import { by } from '../../lib/appium.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const LIMIT = 'הגעתם למספר הטלפונים המרבי';
export const STATUS_ON = 'מקבל התרעות';
export const STATUS_OFF = 'התרעות כבויות';
/** Строка дополнительного телефона (подпись «מכשיר נוסף · …»). */
export const SECOND = by.contains('מכשיר נוסף');

/** «חשבון» → «מכשירים» → список «הטלפונים בחשבון». */
export async function openDevices(app) {
  await onHome(app);
  await openTab(app, 'חשבון');
  const row = await app.scrollTo(by.begins('מכשירים'), { what: 'строка «מכשירים» в «חשבון»' });
  await row.click();
  await app.waitFor(by.contains('הטלפונים בחשבון'), { timeout: 20000, what: 'список «הטלפונים בחשבון»' });
}

/** Текст строки дополнительного телефона (name/label) или null, если его нет в списке. */
export async function secondRowText(app) {
  const els = await app.findAll(SECOND);
  if (!els.length) return null;
  const texts = await Promise.all(els.map(async (e) => String((await e.attr('label').catch(() => '')) || (await e.attr('name').catch(() => '')) || '')));
  // Самая полная подпись (строка-контейнер содержит имя, роль и статус).
  return texts.sort((a, b) => b.length - a.length)[0];
}
